local GlobalAddonName = ...
---@class AddonDB
local AddonDB = select(2, ...)
local MRT = GMRT

---@class ReminderModule: MRTmodule
local module = MRT.A.Reminder
if not module then return end
if MRT.isClassic then return end
---@class ELib
local ELib, L = MRT.lib, MRT.L
---@class MLib
local MLib = AddonDB.MLib

---@class Locale
local LR = AddonDB.LR

-- remove timeline data for bosses that do not exist in EJ
AddonDB:RegisterCallback("ENCOUNTER_JOURNAL_PARSED", function()
	for k, v in next, module.TimelineData do
		if k > 0 and not AddonDB.EJ_DATA.encounterIDtoEJ[k] then
			module.TimelineData[k] = nil
		end
	end
end)


--[[
[key] = { -- key is dungeon encounter id or negative instance id
m = true, -- assumes timelines are children of this entry, if not present then this table is a timeline
{
n = "custom timeline name",
c = "comment",
-- phase info for raid bosses
p={0,119.1,158.1,216.3,259.6,295.7,n={1,2,1.5,2,2.5,3},nc={1,1,1,2,1,1}}, -- array for phase change timings, n for phase names, nc for phase counters
-- phase info for mythic+
p={309.3,543.8,1063.3,1176.5,1576.4,1857.2,n={-3328,0,-3332,0,-3333,0}}, -- array for boss pull timings, negative values in n are dungeon encounter ids, 0 for boss fight end
d = {difficultyID, duration, k=keystoneLevel},
PTR = true? -- indicates that this timeline is from testing realms,
events = { CLEU events are gone in midnight
	[event] = {
		[spellID] = {time1, {time2, r=10}, ... where r is amount of this event being repeated in a short window
}
numeric keys are
[spellID] = {time1, time2, ... , cast=x, d=y,
wheere time could be a number or {time, d=duration} or {time, c=castDuration} if duration/cast is not the same length on each cast

}
}
]]

