-- [-instanceID]={ {n="Wing1 Name", ...}, {n="Wing2 Name", ...}  }

}



local function createBossTimelinesFromInstance(v)
	if v.p then
		local bossStart
		local bossEnd
		local encounterID
		for i, time in ipairs(v.p) do
			local n = v.p.n[i]

			if n < 0 then -- boss start
				bossStart = time
				encounterID = -n
				bossEnd = nil
			elseif n == 0 then -- boss end
				bossEnd = time
			end

			if bossStart and bossEnd then
				local bossData = {
					d = {v.d[1], v.d[1] + bossEnd - bossStart},
					PTR=v.PTR,
				}
				module.TimelineData[encounterID] = module.TimelineData[encounterID] or {m=true}

				tinsert(module.TimelineData[encounterID], bossData)

				for spell, spellTimes in next, v do
					if type(spell) == "number" then
						for _, t in ipairs(spellTimes) do
							local timestamp
							if type(t) == "table" then
								timestamp = t[1]
							else
								timestamp = t
							end

							if timestamp >= bossStart and timestamp <= bossEnd then
								bossData[spell] = bossData[spell] or {cast=spellTimes.cast, d=spellTimes.d}
								local newT
								if type(t) == "table" then
									newT = CopyTable(t)
									newT[1] = t[1] - bossStart
								else
									newT = t - bossStart
								end
								bossData[spell][#bossData[spell]+1] = newT
							end
						end
					end
				end

				bossStart, bossEnd = nil, nil
			end
		end
	end
end

-- create separete boss timelines from full instance timelines
local instanceTimelines = {}
for k, v in pairs(module.TimelineData) do
	if k < 0 then -- instances
		if v.m then
			for _, vm in ipairs(v) do
				tinsert(instanceTimelines, vm)
			end
		else
			tinsert(instanceTimelines, v)
		end
	end
end

for _, instanceTimeline in next, instanceTimelines do
	createBossTimelinesFromInstance(instanceTimeline)
end
